/**
 * Kho từ vựng bổ sung — phần 57b (Bài 57: N2). Do agent soạn; bai57.ts gom các phần lại.
 * Id mục: `b57-kho-NN-…`. Xem bai57.ts.
 *
 * Phần B = chủ đề 11–20 (phần A — kho57a.ts — có mục giới thiệu b57-kho-00 + chủ đề 1–10):
 *   11 môi trường & năng lượng · 12 kinh doanh & công ty · 13 giao tiếp, thái độ & con người · 14 đời sống đô thị & nhà ở ·
 *   15 truyền thông & báo chí · 16 katakana N2 · 17 danh từ trừu tượng · 18 慣用句 (thành ngữ) · 19 同音異義語 / 同訓異字 ·
 *   20 語形成 (tiền tố / hậu tố).
 * CHỐNG TRÙNG (09/11/2026): mọi từ đã đối chiếu (biểu ký + cách đọc, cả dạng có ます/する/ngoặc) với danh sách 4.413 từ đã
 * dạy ở Bài 0–55 + kho N3 (Bài 56) và với phần A (kho57a.ts) — từ đã dạy thì BỎ, chỉ nhắc "(Bài N)" / "(Mục N)" trong dòng
 * `more` khi cần phân biệt. Mục 19 dạy từ CHƯA học làm mục chính; từ đã học chỉ đứng cạnh để so.
 * Cấp JLPT trong `more` là ƯỚC LƯỢNG theo các bảng tham khảo phổ biến (JLPT không công bố danh sách chính thức).
 * Katakana: gốc từ ghi theo từ điển (英 = tiếng Anh, 和製英語 = Nhật tự ghép từ tiếng Anh, 独 = tiếng Đức, 仏 = tiếng Pháp…).
 * Hình: tên trong scripts/hinh/fluent-catalog.json (Fluent Emoji).
 */
import type { Block, Lesson } from '@/components/sach-hoc/types';

type Tu = Extract<Block, { t: 'vocab' }>['items'][number];
/** Một từ: biểu ký {漢字|かな} · loại từ · romaji · nghĩa · câu ví dụ · romaji câu · nghĩa câu · mở rộng (cụm đi kèm, phân biệt, cấp JLPT ước lượng). */
const T = (w: string, pos: string, ipa: string, vi: string, ex: string, exRo: string, exVi: string, more: string): Tu => ({
  w, pos, ipa, vi, ex, exVi, exRo, more,
});

type Mcq = Extract<Block, { t: 'mcq' }>['items'][number];
/**
 * Câu trắc nghiệm: viết đáp án ĐÚNG trước rồi các đáp án nhiễu; hàm đặt đáp án đúng vào vị trí `vt` (0–3) — vị trí
 * cố định (tiến độ lưu theo câu không đổi), mỗi mục rải đều đáp án đúng ra cả 4 ô.
 */
const MQ = (vt: number, q: string, dung: string, sai: string[], why: string): Mcq => {
  const k = Math.min(Math.max(vt, 0), sai.length);
  return { q, options: [...sai.slice(0, k), dung, ...sai.slice(k)], correct: k, why };
};

/**
 * Đáp án gõ tay: viết một lần bằng {漢字|かな}, hàm sinh đủ cách viết chữ Hán / kana (máy chấm đã tự bỏ dấu câu,
 * dấu cách). Phần tử đầu = dạng toàn chữ Hán, là đáp án hiển thị.
 */
const V = (...xs: string[]): string[] => {
  const out = new Set<string>();
  for (const x of xs) {
    const slots = x
      .split(/(\{[^|}]+\|[^}]+\})/)
      .filter(Boolean)
      .map((p) => {
        const m = /^\{([^|}]+)\|([^}]+)\}$/.exec(p);
        return m ? [m[1], m[2]] : [p];
      });
    let acc = [''];
    for (const s of slots) acc = acc.flatMap((a) => s.map((c) => a + c));
    acc.forEach((a) => out.add(a));
  }
  return [...out];
};


